(() => {
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const periods=s=>s.origins?.periods||[];
 const absorbed=s=>s.origins?.absorbedPhases?.[s.id]||[];
 const visible=s=>(s.chronicle?.periods||[]).map((p,i)=>({p,i})).filter(x=>!absorbed(s).includes(x.i));
 const anchor=p=>'history-'+p.id;
 const firstHref=s=>periods(s).length?`#/story/${s.id}/${anchor(periods(s)[0])}`:`#/story/${s.id}`;
 function toc(s){return periods(s).length?`<div class="toc-section-label">起源与沿革</div>${periods(s).map(p=>`<a href="#${anchor(p)}" data-anchor="${anchor(p)}">${esc(p.title)}</a>`).join('')}<div class="toc-section-label">近现代事件</div>${visible(s).map(({p,i})=>`<a href="#part-${i}" data-anchor="part-${i}">${esc(p.title)}</a>`).join('')}${absorbed(s).length?'<a href="#history-supplements" data-anchor="history-supplements">前史补记与人物旧事</a>':''}`:'';}
 function render(s){if(!periods(s).length)return '';const names=s.people.map(x=>x[0]);return `<section class="regional-origins" id="regional-origins"><div class="origin-part-heading"><div class="eyebrow">ORIGINS & HISTORICAL DEVELOPMENT</div><h2>起源与历史沿革</h2><p>从最早可考的建制与社会变迁，读到当代故事开始之前。</p></div>${periods(s).map((p,i)=>`<section class="chapter-section origin-period" id="${anchor(p)}"><div class="period-label"><span>${String(i+1).padStart(2,'0')}</span>${esc(p.period)}</div><h2>${esc(p.title)}</h2>${p.body.split(/\n\s*\n/).filter(Boolean).map(t=>`<p>${window.REGION_UI.inline(t,[...names,...p.people])}</p>`).join('')}${p.people.length?`<div class="origin-people"><small>相关人物与叙述线索</small>${window.REGION_UI.peopleLinks(p.people,true)}</div>`:''}<div class="biography-evidence">材料：${p.refs.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.label)} ↗</a>${r.evidence==='transcription'?'<span class="origin-evidence-tag">原作资料转录</span>':''}`).join('；')}</div></section>`).join('')}<details class="origin-chronology-note"><summary>沿革资料的时序说明</summary><p>${esc(s.origins.chronologyNote)}</p></details></section>`;}
 function modernHeading(s){return periods(s).length?`<header class="modern-part-heading"><div class="eyebrow">CONTEMPORARY EVENTS</div><h2>近现代事件</h2><p>${esc(s.modernIntro||'')}</p></header>`:'';}
 function sources(s){const o=s.origins;if(!o)return '';const refs=[...new Map(o.periods.flatMap(p=>p.refs).map(r=>[r.label+'|'+r.url,r])).values()];return `<h3>地区沿革材料</h3><p>${esc(o.scope)}</p><p>${esc(o.chronologyNote)}</p><ol>${refs.map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.label)} ↗</a>${r.note?`<small> ${esc(r.note)}</small>`:''}</li>`).join('')}</ol><h3>近现代事件材料</h3>`;}
 function overview(r,full){const o=window.REGIONAL_ORIGINS?.regions[r.id],story=window.TERRA.stories.find(s=>s.region===r.id);return o?`<div class="region-origin-overview"><span>起源与历史沿革 · ${o.periods.length} 个阶段</span><p>${esc(full?o.intro:'开启完整阅读后，可按时序查阅地区起源、建制与历史变迁。')}</p><a href="${firstHref(story)}">从最早沿革读起 ↗</a></div>`:'';}
 window.ORIGIN_UI={periods,absorbed,visible,anchor,firstHref,toc,render,modernHeading,sources,overview};
})();
